#include <set>
#include <algorithm>

void demonstrate_constness() {
    std::set<int> s = {10, 20, 30};
    auto it = s.begin();

    // *it = 15; // ERROR: assignment to read-only location

    // Correct way to remove an element by value:
    size_t removed_count = s.erase(20);

    // Pitfall: std::remove does not work for sets
    // std::remove(s.begin(), s.end(), 10); 
    // ^ This compiles but is meaningless/ineffective 
    // because elements cannot be overwritten.
}
